stack.push(1);
assert.strictEqual(stack.size(), 1);
assert.strictEqual(stack.peek(), 1);

// Test pop
stack.push(2);
assert.strictEqual(stack.pop(), 2);
assert.strictEqual(stack.size(), 1);

// Test peek
assert.strictEqual(stack.peek(), 1);

// Test size
