stack.pop();
assert.strictEqual(stack.isEmpty(), true);

// Test pop on empty stack
try {
  stack.pop();
  assert.fail("Expected an error to be thrown");
} catch (e) {
  assert.strictEqual(e.message, "Stack is empty");
}

// Test peek on empty stack
try {
  stack.peek();
  assert.fail("Expected an error to be thrown");
} catch (e) {
  assert.strictEqual(e.message, "Stack is empty");
}

console.log("All tests passed!");
